export interface HelpCatalogItem {
  id: `help:${string}`;
  title: string;
  keywords: string[];
  body: string;
}

interface OverviewBlocks {
  what: string;
  where: string;
  /** 子细节条目的标题清单（不含 id；规划器从目录里按 id+标题选择）。 */
  topics?: string[];
  pitfall?: string;
}

interface DetailBlocks {
  steps: string;
  limits: string;
  pitfalls: string;
}

function helpOverview(id: string, title: string, keywords: string[], blocks: OverviewBlocks): HelpCatalogItem {
  const lines = [
    `是什么：${blocks.what}`,
    `在哪找：${blocks.where}`,
  ];
  if (blocks.topics?.length) lines.push(`细节清单：${blocks.topics.join('、')}`);
  if (blocks.pitfall) lines.push(`常见坑：${blocks.pitfall}`);
  return { id: `help:${id}`, title, keywords, body: lines.join('\n') };
}

function helpDetail(id: string, title: string, keywords: string[], blocks: DetailBlocks): HelpCatalogItem {
  return {
    id: `help:${id}`,
    title,
    keywords,
    body: [
      `操作步骤：${blocks.steps}`,
      `参数与限制：${blocks.limits}`,
      `常见坑：${blocks.pitfalls}`,
    ].join('\n'),
  };
}

