function cloneItem(item: HelpCatalogItem): HelpCatalogItem {
  return { ...item, keywords: [...item.keywords] };
}

/** 返回可安全交给规划器的版本化帮助目录副本。 */
export function buildHelpCatalog(): HelpCatalogItem[] {
  return HELP_CATALOG.map(cloneItem);
}

/** 按请求顺序读取已注册帮助条目；忽略未知 id，并对重复 id 去重。 */
export function readHelpSections(ids: readonly string[]): HelpCatalogItem[] {
  const byId = new Map(HELP_CATALOG.map(item => [item.id, item]));
  const seen = new Set<string>();
  const result: HelpCatalogItem[] = [];
  for (const id of ids) {
    if (seen.has(id)) continue;
    seen.add(id);
    const item = byId.get(id as HelpCatalogItem['id']);
    if (item) result.push(cloneItem(item));
  }
  return result;
}
